/// The points keep marks with 1, whole and in order, into data at point_step bytes each.
pub fn point_cloud_select(cloud: &PointCloud, keep: &[u8]) -> Result<PointCloud, MathError> {
    let c_cloud = CloudRaw::new(cloud);
    check(unsafe { ffi::rant_point_cloud_check(&c_cloud.raw) })?;
    if keep.len() != c_cloud.raw.size / c_cloud.raw.point_step as usize { return Err(MathError::Argument); }
    let mut n = 0u32;
    room(unsafe { ffi::rant_point_cloud_select(&c_cloud.raw, keep.as_ptr(), std::ptr::null_mut(), &mut n) })?;
    let mut out = cloud_like(&c_cloud.raw);
    out.data = vec![0u8; n as usize * c_cloud.raw.point_step as usize];
    check(unsafe { ffi::rant_point_cloud_select(&c_cloud.raw, keep.as_ptr(), out.data.as_mut_ptr(), &mut n) })?;
    Ok(out)
}

